mapper.select:
SELECT * FROM article

    WHERE article.type=#{type}

ORDER BY article.updated_date_time DESC
LIMIT #{offset},#{size}

SELECT *
FROM article
WHERE article.student_id = #{studentId}
ORDER BY article.updated_date_time DESC
LIMIT #{offset},#{size}

SELECT COUNT(*)
FROM article
WHERE updated_date_time > #{updatedDateTime}

SELECT COUNT(*)
FROM article
WHERE article.student_id = #{studentId}

SELECT * FROM (SELECT a.*,ROW_NUMBER() OVER (
PARTITION BY a.type
ORDER BY a.updated_date_time DESC, a.id DESC) AS row_num
FROM article a) t
WHERE t.row_num <=#{size}
ORDER BY t.type ASC, t.updated_date_time DESC, t.id DESC;
